use std::{env,fs,io::Write};
fn main()->Result<(),Box<dyn std::error::Error>>{let a:Vec<_>=env::args().collect();if a.len()<4||a.len()>5{return Err("b27 c|d input output [auto|store|huffman|lz|range]".into())}if fs::metadata(&a[2])?.len()> (b27_primitives::LIMIT*3+2048) as u64{return Err("limit".into())}let x=fs::read(&a[2])?;let mode=match a.get(4).map(String::as_str).unwrap_or("auto"){"auto"=>255,"store"=>0,"huffman"=>1,"lz"=>4,"range"=>7,_=>return Err("mode".into())};let y=match a[1].as_str(){"c"=>b27_primitives::compress(&x,mode),"d"=>b27_primitives::decompress(&x),_=>return Err("op".into())}?;fs::OpenOptions::new().write(true).create_new(true).open(&a[3])?.write_all(&y)?;Ok(())}
